benchmark_predictions<-function(model_cohorts,reference_model_id,metrics,matching_policy,multiple_comparisons,design,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);entries<-.ex_object(model_cohorts,'model_cohorts');models<-.ex_ids(sort(names(entries)),'model IDs');requested<-.ex_ids(metrics,'metrics');if(length(models)<2L||!(reference_model_id%in%models)) .cr_error('BENCHMARK_MODELS','Two or more models including reference required');if(length(setdiff(requested,c('brier','log_loss','auc','gini','calibration_error','mean_pd')))) .cr_error('BENCHMARK_METRIC','Unknown paired metric');if(!(matching_policy%in%c('strict','intersection'))||!(multiple_comparisons%in%c('none','bonferroni'))) .cr_error('BENCHMARK_POLICY','Declare matching and multiplicity');if(d$target$conditioning!='performing'||d$target$time_unit!='days') .cr_error('BENCHMARK_TARGET','Performing day-horizon cohort target required');maps<-manifests<-structure(list(),names=character());target<-NULL
 for(model_id in models){entry<-.ex_object(entries[[model_id]],'model entry');bundle<-.mm_cohort(entry$cohort);for(key in c('model_version','parameter_version','model_fingerprint')).vb_string(entry[[key]],key);known<-.cr_data_date(entry$training_known_at,'training_known_at');rows<-bundle$rows;.ex_ids(lapply(rows,function(r)r$case_id),'cohort case IDs',empty=TRUE)
 if(any(vapply(rows,function(r)r$model_id!=model_id||r$model_version!=entry$model_version,logical(1)))) .cr_error('BENCHMARK_VERSION','Cohort differs from model identity/version');if(any(vapply(rows,function(r)known>.cr_data_date(r$forecast_at,'forecast_at'),logical(1)))) .cr_error('BENCHMARK_LOOKAHEAD','Model unavailable at historical forecast');if(any(vapply(rows,function(r)!is.null(r$prediction_origin)&&!(r$prediction_origin%in%c('HOLDOUT','EXTERNAL')),logical(1)))) .cr_error('BENCHMARK_DESIGN','In-sample cohorts cannot claim heldout comparison');t<-bundle$target_contract
 if(bundle$evaluation_cutoff!=d$evaluation_cutoff||t$event!='default'||t$probability_measure!='PHYSICAL'||t$horizon_days!=d$target$horizon) .cr_error('BENCHMARK_TARGET','Cohort target/horizon/cutoff differs from design');if(!is.null(target)&&.cr_hash(target)!=.cr_hash(t)) .cr_error('BENCHMARK_TARGET','All cohort definitions must match exactly');target<-t
 for(row in rows)if(row$eligible){if(.cr_data_date(row$outcome_end,'outcome_end')>.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff')||.cr_data_date(row$outcome_known_at,'outcome_known_at')>.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff')) .cr_error('BENCHMARK_MATURITY','Eligible outcomes must be mature and known');if(row$target==0&&(is.null(row$complete_through)||.cr_data_date(row$complete_through,'complete_through')<.cr_data_date(row$outcome_end,'outcome_end'))) .cr_error('BENCHMARK_COVERAGE','Negative labels require complete coverage')}
 maps[[model_id]]<-setNames(rows,vapply(rows,function(r)r$case_id,character(1)));manifests[[model_id]]<-entry[c('model_version','parameter_version','model_fingerprint','training_known_at')];manifests[[model_id]]$cohort_hash<-bundle$cohort_hash
 }
 universe<-sort(unique(unlist(lapply(maps,names))));if(matching_policy=='strict'&&any(vapply(maps,function(m)!setequal(names(m),universe),logical(1)))) .cr_error('BENCHMARK_MATCHING','Strict comparison needs identical case IDs');comparison_rows<-exclusions<-list();paired<-character();missing<-setNames(lapply(models,function(m)as.list(sort(setdiff(universe,names(maps[[m]]))))),models)
 for(case_id in universe){present<-lapply(models,function(m)maps[[m]][[case_id]]);present<-Filter(Negate(is.null),present);row<-maps[[reference_model_id]][[case_id]];if(is.null(row))row<-present[[1]];comparison_rows[[length(comparison_rows)+1L]]<-row;reason<-NULL
 if(length(present)!=length(models))reason<-'MISSING_MODEL_PREDICTION'else{for(key in c('entity_id','cluster_id','forecast_at','outcome_end','weight'))if(any(vapply(present,function(r).cr_hash(r[[key]])!=.cr_hash(present[[1]][[key]]),logical(1)))) .cr_error('BENCHMARK_ALIGNMENT','Matched identities/dates/weights differ');labels<-unique(unlist(lapply(present,function(r)r$target)));if(length(labels)>1L) .cr_error('BENCHMARK_OUTCOME','Common observed outcome required');if(!all(vapply(present,function(r)r$eligible,logical(1))))reason<-'OUTCOME_NOT_ELIGIBLE_IN_EVERY_COHORT'else if(present[[1]]$weight==0)reason<-'ZERO_EVALUATION_WEIGHT'else paired<-c(paired,case_id)}
 if(!is.null(reason))exclusions[[length(exclusions)+1L]]<-list(prediction_id=case_id,reason=reason)
 }
 for(model_id in models)for(case_id in names(maps[[model_id]]))maps[[model_id]][[case_id]]$eligible<-case_id%in%paired;draws<-.vb_draws(uncertainty,cluster_resamples,comparison_rows,confidence_level)
 calculate<-function(multiplicities=NULL){scores<-setNames(lapply(models,function(m).mm_metrics(unname(maps[[m]][sort(names(maps[[m]]))]),multiplicities)),models);comparisons<-structure(list(),names=character());for(m in setdiff(models,reference_model_id)){comparisons[[m]]<-setNames(lapply(requested,function(metric){a<-scores[[m]][[metric]];b<-scores[[reference_model_id]][[metric]];good<-!is.null(a)&&!is.null(b);list(difference=if(good)a-b else NULL,candidate=a,reference=b,applicability=if(good)'APPLICABLE'else'NOT_APPLICABLE',reason=if(good)NULL else if(metric=='log_loss')'INFINITE_OR_UNIDENTIFIED_LOG_LOSS'else'NON_ESTIMABLE_PAIRED_METRIC')}),requested)};list(scores=scores,comparisons=comparisons)}
 calculated<-calculate();samples<-if(is.null(draws))NULL else lapply(draws,function(draw){multiplicities<-as.list(setNames(draw,vapply(comparison_rows,function(r)r$cluster_id,character(1))));c<-calculate(multiplicities)$comparisons;flat<-structure(list(),names=character());for(m in names(c))for(metric in requested)flat[paste0(m,'/',metric)]<-list(c[[m]][[metric]]$difference);flat});family_size<-(length(models)-1L)*length(requested);marginal_level<-if(multiple_comparisons=='bonferroni')1-(1-confidence_level)/family_size else confidence_level;bands<-.vb_bands(samples,marginal_level);bands$multiple_comparisons<-multiple_comparisons;bands$family_size<-family_size;bands$family_confidence_level<-confidence_level;bands$coverage_claim<-if(multiple_comparisons=='bonferroni')'BONFERRONI_COMBINATION_OF_APPROXIMATE_MARGINAL_BOOTSTRAP_INTERVALS'else'NO_FAMILYWISE_COVERAGE_ADJUSTMENT'
 diagnostics<-list(reference_model_id=reference_model_id,models=manifests,cohort_target_contract=target,matching_policy=matching_policy,missing_cases_by_model=missing,paired_case_ids=as.list(sort(paired)),difference_direction='CANDIDATE_MINUS_REFERENCE',interpretation=list(brier='LOWER_BETTER',log_loss='LOWER_BETTER',auc='HIGHER_BETTER',gini='HIGHER_BETTER',calibration_error='SIGNED_LEVEL_DIFFERENCE_NOT_AUTOMATIC_IMPROVEMENT',mean_pd='LEVEL_DIFFERENCE_NOT_AUTOMATIC_IMPROVEMENT'),comparison_scope='COMMON_MATURE_OBSERVED_CASES_ONLY',outcome_dependent_candidate_selection_not_corrected=TRUE);.vb_result('benchmark_predictions',list(by_model=calculated$scores,paired_differences=calculated$comparisons),d,comparison_rows,exclusions,bands,context,diagnostics,'paired_model_comparison')
}
benchmark_ratings<-function(internal_ratings,benchmark_records,scale_mapping,matching_policy,design,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context,FALSE);rows<-.vb_records(internal_ratings,d);rows<-rows[order(vapply(rows,function(r)r$prediction_id,character(1)))];mapping<-.ex_object(scale_mapping,'scale_mapping');policy<-.ex_object(matching_policy,'matching_policy');for(key in c('mapping_id','version','reference')).vb_string(mapping[[key]],key);known<-.cr_data_date(mapping$known_at,'mapping known_at');if(known>.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff')||any(vapply(rows,function(r)known>.cr_data_date(r$forecast_known_at,'forecast_known_at'),logical(1)))) .cr_error('BENCHMARK_LOOKAHEAD','Mapping must precede comparisons');grades<-.ex_ids(mapping$common_grades,'common_grades');if(length(grades)<2L) .cr_error('BENCHMARK_SCALE','Two or more common grades required')
 for(side in c('internal','benchmark')){spec<-.ex_object(mapping[[side]],paste(side,'scale'));for(key in c('scale_id','scale_version')).vb_string(spec[[key]],key);source<-.ex_ids(spec$grades,paste(side,'grades'));conversion<-.ex_object(mapping[[paste0(side,'_to_common')]],paste(side,'mapping'));if(!setequal(names(conversion),source)||any(!(unlist(conversion)%in%grades))||any(diff(match(unlist(conversion[source]),grades))<0)) .cr_error('BENCHMARK_SCALE','Complete order-preserving grade mappings required')}
 if(!(policy$benchmark_origin%in%c('EXTERNAL_JUDGEMENT','INTERNAL_DERIVED_MAPPING','INTERNAL_CHALLENGER'))) .cr_error('BENCHMARK_POLICY','Declare benchmark origin');if(!(policy$method%in%c('exact_date','latest_known'))||!(policy$watch_policy%in%c('include','exclude'))||!(policy$kappa_weighting%in%c('unweighted','linear','quadratic'))) .cr_error('BENCHMARK_POLICY','Declare date/watch/kappa policies');provider<-.vb_string(policy$provider_id,'provider_id');age<-.vb_number(policy$max_age_days,'max_age_days',0);if(age!=floor(age)) .cr_error('BENCHMARK_POLICY','Staleness must be integer days');if(!is.list(benchmark_records)||!is.null(names(benchmark_records))||any(!vapply(benchmark_records,.cr_object,logical(1)))) .cr_error('BENCHMARK_RECORDS','Benchmark record array required');external<-benchmark_records[order(vapply(benchmark_records,function(r).vb_string(r$benchmark_id,'benchmark_id'),character(1)))];.ex_ids(lapply(external,function(r)r$benchmark_id),'benchmark IDs',empty=TRUE);dimensions<-c('rating_type','support_concept','currency','rating_philosophy');external_index<-new.env(parent=emptyenv());identity_key<-function(entity,unit,provider).cr_hash(list(entity,unit,provider))
 for(row in external){.ex_target(row$target);for(key in c('entity_id','rating_unit_id','provider_id',dimensions)).vb_string(row[[key]],key);if(!(row$status%in%c('ACTIVE','WATCH','WITHDRAWN','MISSING'))) .cr_error('BENCHMARK_STATUS','Unknown benchmark status');if(.cr_data_date(row$known_at,'benchmark known_at')<.cr_data_date(row$rating_at,'rating_at')) .cr_error('BENCHMARK_LOOKAHEAD','Benchmark cannot be known before effective date');key<-identity_key(row$entity_id,row$rating_unit_id,row$provider_id);old<-if(exists(key,envir=external_index,inherits=FALSE))get(key,envir=external_index,inherits=FALSE)else list();assign(key,c(old,list(row)),envir=external_index)}
 n<-length(rows);left<-right<-integer(n);exclusions<-matches<-audit<-list()
 for(i in seq_along(rows)){row<-rows[[i]];for(key in c('rating_unit_id',dimensions)).vb_string(row[[key]],key);if(!identical(row$scale_id,mapping$internal$scale_id)||!identical(row$scale_version,mapping$internal$scale_version)) .cr_error('BENCHMARK_SCALE','Internal scale/version differs');status<-row$rating_status;if(!(status%in%c('ACTIVE','WATCH','WITHDRAWN','MISSING'))) .cr_error('BENCHMARK_STATUS','Declare internal status');reason<-NULL;selected<-NULL
 if(.cr_data_date(row$as_of,'as_of')>.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff'))reason<-'FUTURE_INTERNAL_RATING'else if(status%in%c('WITHDRAWN','MISSING')||is.null(row$grade))reason<-'NO_ACTIVE_INTERNAL_RATING'else if(status=='WATCH'&&policy$watch_policy=='exclude')reason<-'INTERNAL_WATCH_EXCLUDED'else if(!(row$grade%in%names(mapping$internal_to_common))) .cr_error('BENCHMARK_SCALE','Unknown internal grade')
 key<-identity_key(row$entity_id,row$rating_unit_id,provider);identity<-if(exists(key,envir=external_index,inherits=FALSE))get(key,envir=external_index,inherits=FALSE)else list();available<-Filter(function(r).cr_data_date(r$known_at,'known_at')<=.cr_data_date(row$forecast_known_at,'forecast_known_at')&&.cr_data_date(r$rating_at,'rating_at')<=.cr_data_date(row$as_of,'as_of'),identity);concept<-Filter(function(r)all(vapply(dimensions,function(k)identical(r[[k]],row[[k]]),logical(1)))&&.cr_hash(r$target)==.cr_hash(d$target),available);candidates<-Filter(function(r)policy$method=='latest_known'||r$rating_at==row$as_of,concept)
 if(is.null(reason)){if(!length(identity))reason<-'NO_IDENTITY_MATCH'else if(!length(available))reason<-'NO_KNOWN_BENCHMARK'else if(!length(concept))reason<-'NO_MATCHING_RATING_CONCEPT'else if(!length(candidates))reason<-'NO_MATCHING_RATING_DATE'else{dates<-vapply(candidates,function(r)paste(r$rating_at,r$known_at),character(1));latest<-max(dates);tied<-candidates[dates==latest];if(length(tied)!=1L) .cr_error('BENCHMARK_AMBIGUITY','Equally current benchmark records need upstream resolution');selected<-tied[[1]];elapsed<-as.numeric(.cr_data_date(row$as_of,'as_of')-.cr_data_date(selected$rating_at,'rating_at'))
 if(elapsed>age)reason<-'STALE_BENCHMARK'else if(!identical(selected$scale_id,mapping$benchmark$scale_id)||!identical(selected$scale_version,mapping$benchmark$scale_version))reason<-'BENCHMARK_SCALE_VERSION_MISMATCH'else if(selected$status=='WITHDRAWN')reason<-'WITHDRAWN_BENCHMARK'else if(selected$status=='MISSING'||is.null(selected$grade))reason<-'MISSING_BENCHMARK_GRADE'else if(selected$status=='WATCH'&&policy$watch_policy=='exclude')reason<-'BENCHMARK_WATCH_EXCLUDED'else if(!(selected$grade%in%names(mapping$benchmark_to_common))) .cr_error('BENCHMARK_SCALE','Unknown selected benchmark grade')else{a<-mapping$internal_to_common[[row$grade]];b<-mapping$benchmark_to_common[[selected$grade]];left[i]<-match(a,grades);right[i]<-match(b,grades);matches[[length(matches)+1L]]<-list(prediction_id=row$prediction_id,benchmark_id=selected$benchmark_id,entity_id=row$entity_id,rating_unit_id=row$rating_unit_id,internal_grade=row$grade,benchmark_grade=selected$grade,internal_common_grade=a,benchmark_common_grade=b,signed_notch_difference=left[i]-right[i],benchmark_age_days=elapsed,benchmark_known_at=selected$known_at)}
 }}
 audit[[length(audit)+1L]]<-list(prediction_id=row$prediction_id,identity_candidates=length(identity),known_candidates=length(available),concept_candidates=length(concept),date_candidates=length(candidates),selected_benchmark_id=if(is.null(selected))NULL else selected$benchmark_id,status=if(is.null(reason))'MATCHED'else reason);if(!is.null(reason))exclusions[[length(exclusions)+1L]]<-list(prediction_id=row$prediction_id,reason=reason)
 }
 active<-left>0;point<-assess_expert_rating_agreement(as.list(grades[left[active]]),as.list(grades[right[active]]),ordered_grades=grades,rater_pair=c('internal','benchmark'),weighting=policy$kappa_weighting,missing_policy='error')$value;agreement_weights<-.ex_matrix(point$agreement_weights,'agreement weights');draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level);k<-length(grades)
 calculate<-function(draw){table<-matrix(0,k,k);weight<-draw*active;for(i in which(weight>0))table[left[i],right[i]]<-table[left[i],right[i]]+weight[i];N<-sum(table);result<-list(matched_weight=N,confusion_matrix=.ex_rows(table),exact_agreement=NULL,within_one_notch=NULL,mean_signed_notches=NULL,mean_absolute_notches=NULL,kappa=NULL,spearman_rank_correlation=NULL,observed_weighted_agreement=NULL,expected_weighted_agreement=NULL,kappa_applicability='NOT_APPLICABLE',rank_applicability='NOT_APPLICABLE');if(N==0)return(result);joint<-table/N;difference<-outer(seq_len(k),seq_len(k),'-');a<-rowSums(joint);b<-colSums(joint);observed<-sum(joint*agreement_weights);expected<-sum(outer(a,b)*agreement_weights);u<-cumsum(a)-a/2;v<-cumsum(b)-b/2;u<-u-sum(a*u);v<-v-sum(b*v);variance<-sum(a*u^2)*sum(b*v^2);correlation<-if(variance>0)as.numeric(t(u)%*%joint%*%v)/sqrt(variance)else NULL;result$exact_agreement<-sum(diag(joint));result$within_one_notch<-sum(joint[abs(difference)<=1]);result$mean_signed_notches<-sum(joint*difference);result$mean_absolute_notches<-sum(joint*abs(difference));result['kappa']<-list(if(expected>=1-1e-15)NULL else (observed-expected)/(1-expected));result['spearman_rank_correlation']<-list(correlation);result$observed_weighted_agreement<-observed;result$expected_weighted_agreement<-expected;result$kappa_applicability<-if(expected>=1-1e-15)'NOT_APPLICABLE'else'APPLICABLE';result$rank_applicability<-if(is.null(correlation))'NOT_APPLICABLE'else'APPLICABLE';result}
 metrics<-calculate(rep(1,n));keys<-c('exact_agreement','within_one_notch','mean_signed_notches','mean_absolute_notches','kappa','spearman_rank_correlation');samples<-if(is.null(draws))NULL else lapply(draws,function(draw)calculate(draw)[keys]);used<-unique(vapply(matches,function(m)m$benchmark_id,character(1)));diagnostics<-list(scale_mapping=mapping,matching_policy=policy,matches=matches,matching_audit=audit,benchmark_fingerprint=.cr_hash(external),ordered_common_grades=as.list(grades),notch_direction='POSITIVE_INTERNAL_WORSE_THAN_BENCHMARK',benchmark_is_ground_truth=FALSE,comparison_type=if(policy$benchmark_origin=='INTERNAL_DERIVED_MAPPING')'INTERNAL_MAPPING_CHECK'else paste0(policy$benchmark_origin,'_AGREEMENT'),independent_outcome_calibration_evidence=FALSE,no_fallback_past_known_withdrawal=TRUE,benchmark_count=length(external),distinct_benchmarks_used=length(used),unused_benchmark_ids=as.list(sort(setdiff(vapply(external,function(r)r$benchmark_id,character(1)),used))));.vb_result('benchmark_ratings',metrics,d,rows,exclusions,.vb_bands(samples,confidence_level),context,diagnostics,'ordinal_rating_agreement')
}
